using System;
using System.Text.Json.Serialization;
using AmazonSwf.Core.Enum;

namespace AmazonSwf.Models.Enums;

/// <summary>
/// The cause of the failure. This information is generated by the system and can be useful for diagnostic purposes. When cause is set to OPERATION_NOT_PERMITTED, the decision fails because it lacks sufficient permissions. For details and example IAM policies, see Using IAM to Manage Access to Amazon SWF Workflows in the Amazon SWF Developer Guide.
/// </summary>
[JsonConverter(typeof(StringEnumConverter<Cause12>))]
public sealed record Cause12 : OpenStringEnum<Cause12>
{
    private Cause12(string value) : base(value)
    {
    }

    public static readonly Cause12 WorkflowTypeDoesNotExist = new("WORKFLOW_TYPE_DOES_NOT_EXIST");

    public static readonly Cause12 WorkflowTypeDeprecated = new("WORKFLOW_TYPE_DEPRECATED");

    public static readonly Cause12 OpenChildrenLimitExceeded = new("OPEN_CHILDREN_LIMIT_EXCEEDED");

    public static readonly Cause12 OpenWorkflowsLimitExceeded = new("OPEN_WORKFLOWS_LIMIT_EXCEEDED");

    public static readonly Cause12 ChildCreationRateExceeded = new("CHILD_CREATION_RATE_EXCEEDED");

    public static readonly Cause12 WorkflowAlreadyRunning = new("WORKFLOW_ALREADY_RUNNING");

    public static readonly Cause12 DefaultExecutionStartToCloseTimeoutUndefined = new(
        "DEFAULT_EXECUTION_START_TO_CLOSE_TIMEOUT_UNDEFINED");

    public static readonly Cause12 DefaultTaskListUndefined = new("DEFAULT_TASK_LIST_UNDEFINED");

    public static readonly Cause12 DefaultTaskStartToCloseTimeoutUndefined = new(
        "DEFAULT_TASK_START_TO_CLOSE_TIMEOUT_UNDEFINED");

    public static readonly Cause12 DefaultChildPolicyUndefined = new("DEFAULT_CHILD_POLICY_UNDEFINED");

    public static readonly Cause12 OperationNotPermitted = new("OPERATION_NOT_PERMITTED");

    public TResult Match<TResult>(Func<TResult> onWorkflowTypeDoesNotExist,
        Func<TResult> onWorkflowTypeDeprecated,
        Func<TResult> onOpenChildrenLimitExceeded,
        Func<TResult> onOpenWorkflowsLimitExceeded,
        Func<TResult> onChildCreationRateExceeded,
        Func<TResult> onWorkflowAlreadyRunning,
        Func<TResult> onDefaultExecutionStartToCloseTimeoutUndefined,
        Func<TResult> onDefaultTaskListUndefined,
        Func<TResult> onDefaultTaskStartToCloseTimeoutUndefined,
        Func<TResult> onDefaultChildPolicyUndefined,
        Func<TResult> onOperationNotPermitted,
        Func<string, TResult> otherwise) =>
        this switch
        {
            _ when this == WorkflowTypeDoesNotExist => onWorkflowTypeDoesNotExist(),
            _ when this == WorkflowTypeDeprecated => onWorkflowTypeDeprecated(),
            _ when this == OpenChildrenLimitExceeded => onOpenChildrenLimitExceeded(),
            _ when this == OpenWorkflowsLimitExceeded => onOpenWorkflowsLimitExceeded(),
            _ when this == ChildCreationRateExceeded => onChildCreationRateExceeded(),
            _ when this == WorkflowAlreadyRunning => onWorkflowAlreadyRunning(),
            _ when this ==
                DefaultExecutionStartToCloseTimeoutUndefined => onDefaultExecutionStartToCloseTimeoutUndefined(),
            _ when this == DefaultTaskListUndefined => onDefaultTaskListUndefined(),
            _ when this == DefaultTaskStartToCloseTimeoutUndefined => onDefaultTaskStartToCloseTimeoutUndefined(),
            _ when this == DefaultChildPolicyUndefined => onDefaultChildPolicyUndefined(),
            _ when this == OperationNotPermitted => onOperationNotPermitted(),
            _ => otherwise(Value)
        };

    public void Match(Action onWorkflowTypeDoesNotExist,
        Action onWorkflowTypeDeprecated,
        Action onOpenChildrenLimitExceeded,
        Action onOpenWorkflowsLimitExceeded,
        Action onChildCreationRateExceeded,
        Action onWorkflowAlreadyRunning,
        Action onDefaultExecutionStartToCloseTimeoutUndefined,
        Action onDefaultTaskListUndefined,
        Action onDefaultTaskStartToCloseTimeoutUndefined,
        Action onDefaultChildPolicyUndefined,
        Action onOperationNotPermitted,
        Action<string> otherwise)
    {
        if (this == WorkflowTypeDoesNotExist) onWorkflowTypeDoesNotExist();
        else if (this == WorkflowTypeDeprecated) onWorkflowTypeDeprecated();
        else if (this == OpenChildrenLimitExceeded) onOpenChildrenLimitExceeded();
        else if (this == OpenWorkflowsLimitExceeded) onOpenWorkflowsLimitExceeded();
        else if (this == ChildCreationRateExceeded) onChildCreationRateExceeded();
        else if (this == WorkflowAlreadyRunning) onWorkflowAlreadyRunning();
        else if (this == DefaultExecutionStartToCloseTimeoutUndefined) onDefaultExecutionStartToCloseTimeoutUndefined();
        else if (this == DefaultTaskListUndefined) onDefaultTaskListUndefined();
        else if (this == DefaultTaskStartToCloseTimeoutUndefined) onDefaultTaskStartToCloseTimeoutUndefined();
        else if (this == DefaultChildPolicyUndefined) onDefaultChildPolicyUndefined();
        else if (this == OperationNotPermitted) onOperationNotPermitted();
        else otherwise(Value);
    }
}
